insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$governor$t$, $t$Governor$t$, $t$ৰাজ্যপাল$t$, $t$The constitutional head of a state, appointed by the President of India.$t$, $t$ভাৰতৰ ৰাষ্ট্ৰপতিয়ে নিযুক্তি দিয়া ৰাজ্যৰ সাংবিধানিক মুৰব্বী।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$chief-minister$t$, $t$Chief Minister$t$, $t$মুখ্যমন্ত্ৰী$t$, $t$The head of the state government, usually the leader of the party with a majority in the Assembly.$t$, $t$ৰাজ্য চৰকাৰৰ মুৰব্বী, সাধাৰণতে বিধানসভাত সংখ্যাগৰিষ্ঠ দলৰ নেতা।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$council-of-ministers$t$, $t$Council of Ministers$t$, $t$মন্ত্ৰিপৰিষদ$t$, $t$The team of ministers, led by the Chief Minister, that runs the state government.$t$, $t$মুখ্যমন্ত্ৰীৰ নেতৃত্বত ৰাজ্য চৰকাৰ চলোৱা মন্ত্ৰীসকলৰ দল।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$unicameral$t$, $t$Unicameral$t$, $t$এক সদনীয়$t$, $t$A legislature with only one house. Assam has only a Legislative Assembly, no Legislative Council.$t$, $t$এটা মাত্ৰ সদন থকা বিধানমণ্ডল। অসমত কেৱল বিধানসভা আছে, বিধান পৰিষদ নাই।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$speaker$t$, $t$Speaker$t$, $t$অধ্যক্ষ$t$, $t$The member who runs the meetings of the Assembly and keeps order in the House.$t$, $t$বিধানসভাৰ অধিৱেশন পৰিচালনা কৰা আৰু সদনত শৃংখলা ৰক্ষা কৰা সদস্য।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$high-court$t$, $t$High Court$t$, $t$উচ্চ ন্যায়ালয়$t$, $t$The highest court in a state (or group of states), below the Supreme Court of India.$t$, $t$ভাৰতৰ উচ্চতম ন্যায়ালয়ৰ তলত, এখন ৰাজ্যৰ (বা কেইবাখনো ৰাজ্যৰ) সৰ্বোচ্চ ন্যায়ালয়।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$bench$t$, $t$Bench (of a court)$t$, $t$ন্যায়পীঠ$t$, $t$A branch of a court that sits in another city so that people there need not travel far.$t$, $t$আন এখন চহৰত বহা ন্যায়ালয়ৰ শাখা, যাতে তাৰ মানুহে দূৰলৈ যাব নালাগে।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$sixth-schedule$t$, $t$Sixth Schedule$t$, $t$ষষ্ঠ অনুসূচী$t$, $t$A part of the Constitution of India that lets tribal areas of Assam, Meghalaya, Tripura and Mizoram govern themselves through autonomous councils.$t$, $t$ভাৰতীয় সংবিধানৰ এটা অংশ, যিয়ে অসম, মেঘালয়, ত্ৰিপুৰা আৰু মিজোৰামৰ জনজাতীয় অঞ্চলক স্বায়ত্তশাসিত পৰিষদৰ জৰিয়তে নিজকে শাসন কৰাৰ অধিকাৰ দিয়ে।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$autonomous-council$t$, $t$Autonomous council$t$, $t$স্বায়ত্তশাসিত পৰিষদ$t$, $t$An elected body that makes laws and runs local matters such as land, forests and customs in a tribal area.$t$, $t$জনজাতীয় অঞ্চলৰ মাটি, অৰণ্য, ৰীতি-নীতি আদি স্থানীয় বিষয়ত আইন প্ৰণয়ন আৰু প্ৰশাসন চলোৱা নিৰ্বাচিত অনুষ্ঠান।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$memorandum-of-settlement$t$, $t$Memorandum of Settlement$t$, $t$বুজাবুজিৰ চুক্তি$t$, $t$A written peace agreement between the government and a group, setting out what each side agrees to.$t$, $t$চৰকাৰ আৰু কোনো গোটৰ মাজত কোনে কি মানি ল'ব তাক লিখিতভাৱে উল্লেখ কৰা শান্তি চুক্তি।$t$) on conflict (slug) do nothing;
