insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$গুৱাহাটী {{term:high-court|উচ্চ ন্যায়ালয়}} চাৰিখন ৰাজ্যৰ উচ্চ ন্যায়ালয়: অসম, অৰুণাচল প্ৰদেশ, নাগালেণ্ড আৰু মিজোৰাম। ইয়াৰ মুখ্য আসন গুৱাহাটীত।$t$, null from public.content where slug = $t$gauhati-high-court$t$ on conflict do nothing;
