insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Sixth Schedule and autonomous councils$t$, $t$Assam's three Sixth Schedule councils: Bodoland, Karbi Anglong and Dima Hasao.$t$, 'draft', $t$Sixth Schedule to the Constitution of India, Wikipedia: https://en.wikipedia.org/wiki/Sixth_Schedule_to_the_Constitution_of_India
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$The {{term:sixth-schedule|Sixth Schedule}} of the Constitution applies to tribal areas in four states: Assam, Meghalaya, Tripura and Mizoram. These areas are governed by elected {{term:autonomous-council|autonomous councils}}.$t$, null from public.content where slug = $t$sixth-schedule-councils$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'h1', 2, 'heading', 'normal', $t$The three councils of Assam$t$, null from public.content where slug = $t$sixth-schedule-councils$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'l1', 3, 'list', 'verified_fact', $t$Bodoland Territorial Council (2003), headquarters Kokrajhar
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'h2', 4, 'heading', 'normal', $t$Bodoland Territorial Region (BTR)$t$, null from public.content where slug = $t$sixth-schedule-councils$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p2', 5, 'paragraph', 'normal', $t$The Bodoland Territorial Council was created by a {{term:memorandum-of-settlement|Memorandum of Settlement}} dated 10 February 2003. A peace agreement signed on 27 January 2020 formed the Bodoland Territorial Region with more powers.$t$, null from public.content where slug = $t$sixth-schedule-councils$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p3', 6, 'paragraph', 'normal', $t$BTR has five districts: Kokrajhar, Chirang, Baksa, Udalguri and Tamulpur. Its council has 46 members: 40 elected and 6 nominated by the Governor.$t$, null from public.content where slug = $t$sixth-schedule-councils$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'h3', 7, 'heading', 'normal', $t$Karbi Anglong Autonomous Council$t$, null from public.content where slug = $t$sixth-schedule-councils$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'p4', 8, 'paragraph', 'normal', $t$It began as a district council on 17 November 1951 and became the Karbi Anglong Autonomous Council on 23 June 1952. It has 26 members.$t$, null from public.content where slug = $t$sixth-schedule-councils$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'en', 'exam1', 9, 'fact_box', 'exam_fact', $t$Remember for exams: 3 Sixth Schedule councils in Assam; BTR formed by the Bodo Accord of 27 January 2020; BTR HQ Kokrajhar.$t$, null from public.content where slug = $t$sixth-schedule-councils$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$ষষ্ঠ অনুসূচী আৰু স্বায়ত্তশাসিত পৰিষদ$t$, $t$অসমৰ তিনিখন ষষ্ঠ অনুসূচীভুক্ত পৰিষদ: বড়োলেণ্ড, কাৰ্বি আংলং আৰু ডিমা হাছাও।$t$, 'draft', $t$Sixth Schedule to the Constitution of India, Wikipedia: https://en.wikipedia.org/wiki/Sixth_Schedule_to_the_Constitution_of_India
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$সংবিধানৰ {{term:sixth-schedule|ষষ্ঠ অনুসূচী}} চাৰিখন ৰাজ্যৰ জনজাতীয় অঞ্চলত প্ৰযোজ্য: অসম, মেঘালয়, ত্ৰিপুৰা আৰু মিজোৰাম। এই অঞ্চলসমূহ নিৰ্বাচিত {{term:autonomous-council|স্বায়ত্তশাসিত পৰিষদে}} শাসন কৰে।$t$, null from public.content where slug = $t$sixth-schedule-councils$t$ on conflict do nothing;
