insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'h2', 4, 'heading', 'normal', $t$বড়োলেণ্ড আঞ্চলিক অঞ্চল (বি টি আৰ)$t$, null from public.content where slug = $t$sixth-schedule-councils$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p2', 5, 'paragraph', 'normal', $t$২০০৩ চনৰ ১০ ফেব্ৰুৱাৰীৰ {{term:memorandum-of-settlement|বুজাবুজিৰ চুক্তিৰে}} বড়োলেণ্ড আঞ্চলিক পৰিষদ গঠন হয়। ২০২০ চনৰ ২৭ জানুৱাৰীত স্বাক্ষৰিত শান্তি চুক্তিয়ে অধিক ক্ষমতাৰে বড়োলেণ্ড আঞ্চলিক অঞ্চল গঠন কৰে।$t$, null from public.content where slug = $t$sixth-schedule-councils$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p3', 6, 'paragraph', 'normal', $t$বি টি আৰত পাঁচখন জিলা আছে: কোকৰাঝাৰ, চিৰাং, বাক্সা, ওদালগুৰি আৰু তামুলপুৰ। ইয়াৰ পৰিষদত ৪৬ জন সদস্য: ৪০ জন নিৰ্বাচিত আৰু ৬ জন ৰাজ্যপালৰ দ্বাৰা মনোনীত।$t$, null from public.content where slug = $t$sixth-schedule-councils$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'h3', 7, 'heading', 'normal', $t$কাৰ্বি আংলং স্বায়ত্তশাসিত পৰিষদ$t$, null from public.content where slug = $t$sixth-schedule-councils$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'p4', 8, 'paragraph', 'normal', $t$১৯৫১ চনৰ ১৭ নৱেম্বৰত ই জিলা পৰিষদ হিচাপে আৰম্ভ হয় আৰু ১৯৫২ চনৰ ২৩ জুনত কাৰ্বি আংলং স্বায়ত্তশাসিত পৰিষদ হয়। ইয়াৰ সদস্য ২৬ জন।$t$, null from public.content where slug = $t$sixth-schedule-councils$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body, image_url) select id, 'as', 'exam1', 9, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: অসমত ৩ খন ষষ্ঠ অনুসূচীভুক্ত পৰিষদ; ২৭ জানুৱাৰী ২০২০ৰ বড়ো চুক্তিৰে বি টি আৰ গঠন; বি টি আৰৰ মুখ্য কাৰ্যালয় কোকৰাঝাৰ।$t$, null from public.content where slug = $t$sixth-schedule-councils$t$ on conflict do nothing;
